package org.eclipse.kura.core.internal.linux.executor;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.IOException;
import java.util.Map;

import org.apache.commons.exec.CommandLine;
import org.apache.commons.exec.DefaultExecutor;
import org.apache.commons.exec.ExecuteException;
import org.apache.commons.exec.ExecuteWatchdog;
import org.apache.commons.exec.Executor;
import org.eclipse.kura.core.linux.executor.LinuxPid;
import org.eclipse.kura.executor.Pid;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class ExecutorUtilHelperTimeoutTest {

    private static final int HELPER_FAILURE_EXIT_VALUE = 143;

    private final DefaultExecutor executor = mock(DefaultExecutor.class);
    private final ExecutorUtil executorUtil = new ExecutorUtil() {

        @Override
        protected Executor getExecutor() {
            return ExecutorUtilHelperTimeoutTest.this.executor;
        }
    };
    private boolean running;
    private Map<String, Pid> pids;

    @Test
    public void processCheckRunsWithWatchdog() {
        givenHelperFails();

        whenCheckingIfPidIsRunning();

        thenHelperWatchdogIsSet();
        thenPidIsNotRunning();
    }

    @Test
    public void pidLookupRunsWithWatchdog() {
        givenHelperFails();

        whenLookingUpPids();

        thenHelperWatchdogIsSet();
        thenNoPidsAreReturned();
    }

    private void givenHelperFails() {
        try {
            when(this.executor.execute(any(CommandLine.class)))
                    .thenThrow(new ExecuteException("Process exited with an error", HELPER_FAILURE_EXIT_VALUE));
        } catch (IOException e) {
            throw new IllegalStateException(e);
        }
    }

    private void whenCheckingIfPidIsRunning() {
        this.running = this.executorUtil.isRunning(new LinuxPid(1234));
    }

    private void whenLookingUpPids() {
        this.pids = this.executorUtil.getPids(new String[] { "sleep" });
    }

    private void thenHelperWatchdogIsSet() {
        final ArgumentCaptor<ExecuteWatchdog> watchdogCaptor = ArgumentCaptor.forClass(ExecuteWatchdog.class);
        verify(this.executor).setWatchdog(watchdogCaptor.capture());
        assertNotNull(watchdogCaptor.getValue());
    }

    private void thenPidIsNotRunning() {
        assertFalse(this.running);
    }

    private void thenNoPidsAreReturned() {
        assertTrue(this.pids.isEmpty());
    }
}
